import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.CtrpDQpp.js";const i="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",o="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",s="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",l="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",h="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",n="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",q=JSON.parse('{"title":"第 5 章 后台管理界面全解析","description":"","frontmatter":{},"headers":[],"relativePath":"05-dashboard.md","filePath":"05-dashboard.md","lastUpdated":1792595797000}'),p={name:"05-dashboard.md"};function c(g,t,b,u,A,k){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="第-5-章-后台管理界面全解析" tabindex="-1">第 5 章 后台管理界面全解析 <a class="header-anchor" href="#第-5-章-后台管理界面全解析" aria-label="Permalink to &quot;第 5 章 后台管理界面全解析&quot;">​</a></h1><p>🟢 <strong>入门难度</strong> ｜ 一句话导览：从登录 <code>wp-admin</code> 开始，逐项拆解左侧主菜单、设置六大分页的每一个字段、五大角色的能力边界与站点健康工具，把「后台每个按钮是干什么的」一次讲清，并附上固定链接 404、时区、Gravatar 加载慢、忘记管理员密码等高频问题的标准解法。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>能通过 <code>wp-login.php</code> 与 <code>/wp-admin</code> 登录、登出，会用邮件找回密码，理解管理栏在前后台切换中的作用</li><li>说清左侧主菜单每一项的职责，以及管理员、编辑、作者等不同角色看到的菜单差异</li><li>完整走一遍「设置」的六个分页，理解常规、撰写、阅读、讨论、媒体、固定链接、隐私每个字段的影响</li><li>讲清 WordPress 地址与站点地址的区别，知道移动网站目录前必须先做什么</li><li>掌握五大默认角色的能力矩阵与最小权限原则，会新建用户、完善个人资料、签发应用密码</li><li>会使用「工具 → 站点健康」排查环境与配置问题</li></ul><h2 id="_5-1-登录、登出与找回密码" tabindex="-1">5.1 登录、登出与找回密码 <a class="header-anchor" href="#_5-1-登录、登出与找回密码" aria-label="Permalink to &quot;5.1 登录、登出与找回密码&quot;">​</a></h2><h3 id="原理说明" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>WordPress 有两个与登录相关的地址，分工不同：</p><table tabindex="0"><thead><tr><th>地址</th><th>作用</th></tr></thead><tbody><tr><td><code>https://example.com/wp-login.php</code></td><td>登录页本体：验证用户名与密码，处理找回密码</td></tr><tr><td><code>https://example.com/wp-admin</code></td><td>后台入口：未登录访问会被重定向到登录页，登录成功后再跳回后台</td></tr></tbody></table><p>登录成功后，WordPress 会在浏览器写入登录 Cookie。默认会话约 48 小时；登录页勾选「记住我」后延长到约 14 天。换浏览器、换设备、清除 Cookie 都会要求重新登录。</p><h3 id="操作方法-登录与登出" tabindex="-1">操作方法：登录与登出 <a class="header-anchor" href="#操作方法-登录与登出" aria-label="Permalink to &quot;操作方法：登录与登出&quot;">​</a></h3><ol><li>浏览器访问 <code>你的域名/wp-admin</code>，未登录时自动跳转到登录页。</li><li>输入「用户名或电子邮件地址」与「密码」，点击「登录」。</li><li>进入后台首页（仪表盘）。以后每次访问，只要 Cookie 未过期就直接进入。</li><li>登出：把鼠标移到页面右上角管理栏中的「您好，某某」上，在下拉菜单中点「退出」。公用电脑上务必登出。</li></ol><h3 id="找回密码-邮件方式" tabindex="-1">找回密码（邮件方式） <a class="header-anchor" href="#找回密码-邮件方式" aria-label="Permalink to &quot;找回密码（邮件方式）&quot;">​</a></h3><ol><li>在登录页点击「忘记密码？」链接。</li><li>输入用户名或注册邮箱，点击「获取新密码」。</li><li>查收邮件（注意垃圾邮件文件夹），点击邮件中的重置链接，在打开的页面里设置新密码。</li></ol><blockquote><p>💡 邮件方式依赖服务器能正常发信。如果收不到重置邮件，需要改用 phpMyAdmin 或 WP-CLI 重置，见本章 <a href="#_5-12-常见问题速查">5.12 节</a>；邮件发不出去的根因与 SMTP 解决方案见<a href="./10-comments">第 10 章</a>与<a href="./38-troubleshooting">第 38 章</a>。</p></blockquote><h3 id="管理栏-前后台之间的传送带" tabindex="-1">管理栏：前后台之间的传送带 <a class="header-anchor" href="#管理栏-前后台之间的传送带" aria-label="Permalink to &quot;管理栏：前后台之间的传送带&quot;">​</a></h3><p>登录状态下访问前台页面，页面顶部会多出一条黑色的<strong>管理栏（Toolbar）</strong>，它是前后台切换的枢纽：</p><ul><li>左侧：WordPress 图标（关于/文档链接）、站点名称（鼠标悬停可点「仪表盘」回后台）、评论气泡、<strong>「+ 新建」</strong>（快速新建文章/页面/媒体/用户）。</li><li>浏览某篇文章时会出现「编辑文章」，一键直达该文的编辑页。</li><li>右侧：「您好，某某」，下拉可进入「编辑个人资料」或「退出」。</li></ul><p><img src="'+i+'" alt="图 05-2：管理栏与前后台切换"><em>图 05-2：登录后访问前台时页面顶部的管理栏，左侧可回后台、可新建内容，右侧可编辑资料或退出</em></p><h3 id="操作方法-关闭前台管理栏" tabindex="-1">操作方法：关闭前台管理栏 <a class="header-anchor" href="#操作方法-关闭前台管理栏" aria-label="Permalink to &quot;操作方法：关闭前台管理栏&quot;">​</a></h3><ol><li>后台右上角点「您好，某某 → 编辑个人资料」（或左侧「用户 → 个人资料」）。</li><li>找到「工具栏」选项，取消勾选「在浏览站点时显示工具栏」。</li><li>拉到页面底部点「更新个人资料」。此后访问前台不再显示管理栏，后台顶栏不受影响。</li></ol><h3 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：登录地址忘记了怎么办？</strong> 答：先试 <code>/wp-admin</code> 和 <code>/wp-login.php</code>。若安全插件改过登录地址，到站点根目录的 <code>.htaccess</code> 或插件设置里查找；实在找不到可用 WP-CLI 停用该插件（<code>wp plugin deactivate 插件目录名</code>），登录页即恢复原状。</li><li><strong>问：提示「错误：您输入的用户名无效」但用户名没记错？</strong> 答：登录框同时接受用户名和邮箱，试试用注册邮箱登录。还要排除键盘大小写锁定与多余空格。</li></ul><h2 id="_5-2-左侧主菜单逐项详解" tabindex="-1">5.2 左侧主菜单逐项详解 <a class="header-anchor" href="#_5-2-左侧主菜单逐项详解" aria-label="Permalink to &quot;5.2 左侧主菜单逐项详解&quot;">​</a></h2><h3 id="原理说明-1" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-1" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>左侧黑色纵向菜单是后台的骨架，WordPress 按<strong>当前用户的角色</strong>决定显示哪些菜单项。同一套程序，管理员看到全部菜单，订阅者只看到「个人资料」。理解这一点，就不会在换账号后惊呼「菜单丢了」。</p><p><img src="'+o+'" alt="图 05-1：仪表盘总览"><em>图 05-1：管理员视角的后台首页：左侧主菜单 + 顶部管理栏 + 仪表盘小工具（概览、快速草稿、活动、WordPress 活动与新闻）</em></p><h3 id="逐项说明" tabindex="-1">逐项说明 <a class="header-anchor" href="#逐项说明" aria-label="Permalink to &quot;逐项说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>职责</th><th>主要子菜单</th></tr></thead><tbody><tr><td>仪表盘</td><td>后台首页与系统更新</td><td>首页（站点概览小工具）、更新（核心/主题/插件升级入口）</td></tr><tr><td>文章</td><td>博客内容的发布与管理</td><td>全部文章、写文章、分类目录、标签（详见<a href="./06-posts-and-pages">第 06 章</a>、<a href="./09-taxonomies">第 09 章</a>）</td></tr><tr><td>媒体</td><td>图片、文档等附件管理</td><td>媒体库、添加新媒体文件（详见<a href="./08-media-library">第 08 章</a>）</td></tr><tr><td>页面</td><td>静态页面管理（首页、关于我们等）</td><td>全部页面、添加新页面（与文章的区别见<a href="./06-posts-and-pages">第 06 章</a>）</td></tr><tr><td>评论</td><td>读者评论的审核与回复</td><td>评论列表（详见<a href="./10-comments">第 10 章</a>）</td></tr><tr><td>外观</td><td>站点颜值与版式</td><td>主题、自定义/编辑器、小工具、菜单、主题文件编辑器（详见<a href="./11-theme-ecosystem">第 11 章</a>）</td></tr><tr><td>插件</td><td>功能扩展的装与管</td><td>已安装的插件、安装插件、插件文件编辑器</td></tr><tr><td>用户</td><td>账号与角色管理</td><td>全部用户、添加用户、个人资料</td></tr><tr><td>工具</td><td>导入导出与健康检查</td><td>可用工具、导入、导出、站点健康、导出个人数据、抹除个人数据</td></tr><tr><td>设置</td><td>全站行为开关</td><td>常规、撰写、阅读、讨论、媒体、固定链接、隐私</td></tr></tbody></table><blockquote><p>💡 安装插件后，插件可能往主菜单加自己的顶级菜单（如商城、表单插件），或挂在「工具」「设置」下面加子菜单。「设置」分页变多，多半是插件干的。</p></blockquote><h3 id="重点菜单详解" tabindex="-1">重点菜单详解 <a class="header-anchor" href="#重点菜单详解" aria-label="Permalink to &quot;重点菜单详解&quot;">​</a></h3><p><strong>仪表盘</strong>：登录后的落地页。「首页」由若干小工具（概览、快速草稿、活动、WordPress 活动与新闻）拼成，可通过页面顶部的「显示选项」勾选开关各模块，也可直接拖拽重排——这套面板是给人看的速览，不产生任何数据。「更新」子页集中列出核心、主题、插件的可用新版本，出现红色数字角标就意味着有更新待处理（更新策略见<a href="./37-maintenance">第 37 章</a>）。</p><p><strong>文章</strong>：博客站使用频率最高的菜单。「全部文章」支持按分类、日期、作者筛选与批量编辑；「写文章」直达区块编辑器（见<a href="./07-block-editor">第 07 章</a>）；「分类目录」「标签」两个子菜单通向分类法管理（见<a href="./09-taxonomies">第 09 章</a>）。</p><p><strong>媒体</strong>：全站图片、PDF、视频等附件的仓库。图片通常在上传时挂在某篇文章下，但媒体库本身是全站共享的——任何文章都可以复用已上传的文件（管理与编辑技巧见<a href="./08-media-library">第 08 章</a>）。</p><p><strong>页面</strong>：与文章并列的第二种内容形态，承载「关于我们」「联系方式」这类不进博客流的静态内容。页面支持父子层级，但没有分类和标签（文章与页面的完整对比见<a href="./06-posts-and-pages">第 06 章</a>）。</p><p><strong>评论</strong>：读者互动的审核台，待审评论的数量会直接显示在菜单名旁的红圈里。评论系统的架构与反垃圾体系是<a href="./10-comments">第 10 章</a>的全部内容。</p><p><strong>外观</strong>：站点「长什么样」的总开关。经典主题下子菜单为「主题、自定义、小工具、菜单、主题文件编辑器」；启用区块主题后，「自定义」「小工具」会被「编辑器（站点编辑器）」取代，改用区块方式编辑整站模板（两条路线见<a href="./11-theme-ecosystem">第 11 章</a>）。「主题文件编辑器」能直接改 PHP 源码，改错即白屏，<strong>生产环境不建议使用</strong>，很多站点会通过配置常量直接禁用它（见<a href="./32-security">第 32 章</a>）。</p><p><strong>插件</strong>：WordPress 功能的扩展机制。「安装插件」页可在线搜索官方插件目录并一键安装；「已安装的插件」负责启用、停用与删除。和主题文件编辑器一样，「插件文件编辑器」同样慎用。</p><p><strong>用户</strong>：站点全部账号的花名册，支持按角色筛选、批量修改角色。任何人（含订阅者）都至少能看到「个人资料」，维护自己的密码与偏好。</p><p><strong>工具</strong>：运维向功能的集合。「可用工具」里有「分类目录和标签转换器」等按需启用的小工具；「导入」支持从其他平台迁入内容；「导出」打包全站内容为 XML；「站点健康」单独在 5.11 节详解；「导出/抹除个人数据」配合隐私政策使用（见 5.9 节）。</p><p><strong>设置</strong>：全站行为的地基，六个核心分页在 5.3–5.9 节逐一展开。插件注册的分页通常追加在「设置」菜单末尾。</p><h3 id="各角色可见性差异" tabindex="-1">各角色可见性差异 <a class="header-anchor" href="#各角色可见性差异" aria-label="Permalink to &quot;各角色可见性差异&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>管理员</th><th>编辑</th><th>作者</th><th>贡献者</th><th>订阅者</th></tr></thead><tbody><tr><td>仪表盘</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>文章</td><td>全部</td><td>全部</td><td>仅自己的</td><td>仅自己的</td><td>—</td></tr><tr><td>媒体</td><td>全部</td><td>全部</td><td>全部</td><td>—</td><td>—</td></tr><tr><td>页面</td><td>✓</td><td>✓</td><td>—</td><td>—</td><td>—</td></tr><tr><td>评论</td><td>✓</td><td>✓</td><td>—</td><td>—</td><td>—</td></tr><tr><td>外观</td><td>✓</td><td>—</td><td>—</td><td>—</td><td>—</td></tr><tr><td>插件</td><td>✓</td><td>—</td><td>—</td><td>—</td><td>—</td></tr><tr><td>用户</td><td>全部</td><td>仅个人资料</td><td>仅个人资料</td><td>仅个人资料</td><td>仅个人资料</td></tr><tr><td>工具</td><td>全部</td><td>部分</td><td>部分</td><td>部分</td><td>—</td></tr><tr><td>设置</td><td>✓</td><td>—</td><td>—</td><td>—</td><td>—</td></tr></tbody></table><p>记忆法：<strong>内容越往左越「重」，权限越往下越「轻」</strong>——管理员管全站，编辑管内容，作者管自己的文章，订阅者只管自己的资料。</p><h2 id="_5-3-设置-常规" tabindex="-1">5.3 设置：常规 <a class="header-anchor" href="#_5-3-设置-常规" aria-label="Permalink to &quot;5.3 设置：常规&quot;">​</a></h2><p>「设置 → 常规」是全站身份信息的总控台，字段不多但每一个都影响全站。</p><p><img src="'+s+`" alt="图 05-3：常规设置页"><em>图 05-3：设置 → 常规：站点标题、副标题、两个 URL、管理邮箱、成员资格、默认角色、站点语言与时区</em></p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th><th>注意事项</th></tr></thead><tbody><tr><td>站点标题</td><td>站名，出现在浏览器标题、主题页头、邮件落款</td><td>随时可改</td></tr><tr><td>副标题</td><td>一句话简介</td><td>默认值「又一个 WordPress 站点」务必改掉或清空，否则会出现在搜索结果里</td></tr><tr><td>WordPress 地址（URL）</td><td>WordPress <strong>核心程序文件</strong>所在的目录地址</td><td>对应数据库 <code>wp_options.siteurl</code></td></tr><tr><td>站点地址（URL）</td><td>访客在浏览器里输入的<strong>前台访问地址</strong></td><td>对应 <code>wp_options.home</code></td></tr><tr><td>管理电子邮件地址</td><td>接收新用户注册、评论审核等系统通知</td><td>修改后需点击新邮箱里的确认链接才生效</td></tr><tr><td>成员资格</td><td>勾选「任何人都可以注册」后开放注册</td><td>资讯站通常不勾</td></tr><tr><td>新用户默认角色</td><td>开放注册后新账号的角色</td><td><strong>保持「订阅者」</strong>，切勿设为作者以上</td></tr><tr><td>站点语言</td><td>后台与系统文案语言</td><td>用户可在个人资料里单独覆盖后台语言</td></tr><tr><td>时区</td><td>影响发布时间、定时发布、评论时间</td><td>国内选「UTC+8」或「上海」</td></tr><tr><td>日期格式 / 时间格式</td><td>前台日期时间的显示样式</td><td>可选预设或自定义</td></tr><tr><td>星期开始于</td><td>日历小工具/归档的起始日</td><td>习惯选「星期一」</td></tr></tbody></table><h3 id="操作方法-逐项设置常规信息" tabindex="-1">操作方法：逐项设置常规信息 <a class="header-anchor" href="#操作方法-逐项设置常规信息" aria-label="Permalink to &quot;操作方法：逐项设置常规信息&quot;">​</a></h3><ol><li>后台点「设置 → 常规」，先通读一遍每个字段的当前值。</li><li>「站点标题」填站名；「副标题」清空默认值或改成一句不超过 20 字的简介。</li><li>核对「WordPress 地址」与「站点地址」——两者应与浏览器地址栏里的访问地址一致（本地环境形如 <code>http://localhost:8888/站点目录</code>），<strong>确认无误前不要手改</strong>，原理见下节。</li><li>「管理电子邮件地址」填自己真实在用的邮箱。</li><li>确认「成员资格」未勾选；「新用户默认角色」保持「订阅者」。</li><li>「时区」选择「UTC+8」（或城市「上海」），注意选择框下方会实时显示当前换算出的本地时间，可用来核对是否选对。</li><li>日期格式选 <code>Y年n月j日</code> 或自定义 <code>Y-m-d</code>；时间格式按需选 24 小时制。</li><li>拉到底部点「保存更改」，页面顶部出现「设置已保存」即完成。</li></ol><h3 id="原理说明-wordpress-地址-vs-站点地址" tabindex="-1">原理说明：WordPress 地址 vs 站点地址 <a class="header-anchor" href="#原理说明-wordpress-地址-vs-站点地址" aria-label="Permalink to &quot;原理说明：WordPress 地址 vs 站点地址&quot;">​</a></h3><p>绝大多数站点两者相同。把它们设成不同，是为了实现「<strong>程序放在子目录、前台用根域名访问</strong>」的部署方式，例如程序装在 <code>example.com/wp</code>，访客访问 <code>example.com</code> 即可。</p><p><strong>移动目录的坑</strong>：如果你先在服务器上把 WordPress 文件夹从 <code>wp</code> 挪到根目录，再在后台改这两个地址，会出现「改完保存的瞬间后台打不开」的窘境——因为地址与文件位置错位了。正确顺序是：</p><ol><li>先在「设置 → 常规」把两个 URL 改成新地址并保存（此时前台会暂时异常，属正常）。</li><li>立刻把文件移动到新位置（或调整虚拟主机指向）。</li><li>如果已经改错导致后台进不去，用数据库修复：在 <code>wp_options</code> 表把 <code>siteurl</code>、<code>home</code> 两行改回正确值；或用 WP-CLI：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看当前两个地址</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> option</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> siteurl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> option</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> home</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 改回正确地址（把示例域名换成你的）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> option</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> siteurl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://example.com&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> option</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> home</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://example.com&#39;</span></span></code></pre></div><p>地址对不上的更多排查见<a href="./04-installation">第 04 章</a>的重定向循环一节与<a href="./38-troubleshooting">第 38 章</a>。</p><h3 id="操作方法-设置时区与常规信息" tabindex="-1">操作方法：设置时区与常规信息 <a class="header-anchor" href="#操作方法-设置时区与常规信息" aria-label="Permalink to &quot;操作方法：设置时区与常规信息&quot;">​</a></h3><ol><li>后台点「设置 → 常规」。</li><li>填好站点标题、把副标题清空或改成一句简介。</li><li>核对两个 URL 与当前访问地址一致（本地环境是 <code>http://localhost:端口</code> 之类）。</li><li>时区下拉选择「UTC+8」（或城市「上海」）。</li><li>确认「成员资格」未勾选、「新用户默认角色」为「订阅者」。</li><li>拉到底部点「保存更改」，页面顶部出现「设置已保存」即完成。</li></ol><h3 id="常见问题-1" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题-1" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：为什么「管理电子邮件地址」改了没生效？</strong> 答：出于安全，WordPress 会向新邮箱发确认邮件，点击邮件里的链接后才会真正切换；之前的通知仍发旧邮箱。</li></ul><h2 id="_5-4-设置-撰写" tabindex="-1">5.4 设置：撰写 <a class="header-anchor" href="#_5-4-设置-撰写" aria-label="Permalink to &quot;5.4 设置：撰写&quot;">​</a></h2><p>「设置 → 撰写」决定写文章时的默认行为，字段很少：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td>默认文章分类</td><td>写文章不勾选分类时自动归入的分类（初始为「未分类」，改名与替换见<a href="./09-taxonomies">第 09 章</a>）</td></tr><tr><td>默认文章形式</td><td>标准/日志/链接等形式，取决于主题是否支持</td></tr><tr><td>通过电子邮件发表文章</td><td>官方已标记废弃、计划移除，不建议配置使用</td></tr><tr><td>更新服务</td><td>文章发布时自动通知的 ping 服务地址，默认已填好，保持默认即可</td></tr></tbody></table><h3 id="原理说明-2" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-2" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>这一页的每一项都是「发布流程的默认值」：默认分类决定了漏选分类时文章的去向；默认文章形式只在主题声明支持时出现；「通过电子邮件发表文章」是早期通过专用邮箱发帖的旧机制，官方已不建议使用，不必配置；「更新服务」则是在文章发布时主动 ping 搜索引擎与聚合服务，通知它们来抓取新内容——保持默认填好的服务地址即可，留空等于放弃主动通知。</p><h3 id="操作方法-更换默认文章分类" tabindex="-1">操作方法：更换默认文章分类 <a class="header-anchor" href="#操作方法-更换默认文章分类" aria-label="Permalink to &quot;操作方法：更换默认文章分类&quot;">​</a></h3><ol><li>先在「文章 → 分类目录」建好新分类（如「随笔」）。</li><li>回「设置 → 撰写」，把「默认文章分类」切换为「随笔」并保存。</li><li>此后「未分类」才可以被删除或改名。</li></ol><h2 id="_5-5-设置-阅读" tabindex="-1">5.5 设置：阅读 <a class="header-anchor" href="#_5-5-设置-阅读" aria-label="Permalink to &quot;5.5 设置：阅读&quot;">​</a></h2><p>「设置 → 阅读」决定<strong>首页给谁看、看多少</strong>，以及 RSS 和搜索引擎的行为。</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th><th>常见选择</th></tr></thead><tbody><tr><td>您的主页显示</td><td>「您的最新文章」= 博客流；「一个静态页面」= 用指定页面当首页</td><td>博客选前者；企业站/作品站选后者</td></tr><tr><td>主页（静态页面模式下）</td><td>选哪个页面作为首页</td><td>需先建好「首页」页面</td></tr><tr><td>文章页（静态页面模式下）</td><td>选哪个页面承载博客文章列表</td><td>需先建好「博客」页面，留空则没有博客入口</td></tr><tr><td>博客页面至多显示</td><td>列表页每页文章数</td><td>10 上下</td></tr><tr><td>联合供稿（Feed）中显示最近</td><td>RSS 输出的条目数</td><td>默认 10</td></tr><tr><td>对于 Feed 中的每篇文章，包含</td><td>「全文」或「摘要」</td><td>全文方便读者，摘要可引导回访并减少被整体抓取</td></tr><tr><td>对搜索引擎的可见性</td><td>勾选后请求搜索引擎不索引本站</td><td><strong>仅开发期勾选，上线前必须取消</strong>（见<a href="./04-installation">第 04 章</a>安装后设置）</td></tr></tbody></table><h3 id="操作方法-配置静态首页-博客页" tabindex="-1">操作方法：配置静态首页 + 博客页 <a class="header-anchor" href="#操作方法-配置静态首页-博客页" aria-label="Permalink to &quot;操作方法：配置静态首页 + 博客页&quot;">​</a></h3><ol><li>「页面 → 添加新页面」，建一个标题为「首页」的页面并发布；再建一个标题为「博客」的空页面并发布。</li><li>「设置 → 阅读」，「您的主页显示」选择「一个静态页面」。</li><li>「主页」下拉选「首页」，「文章页」下拉选「博客」，保存更改。</li><li>访问前台：域名直达「首页」页面；<code>/blog/</code>（或该页面的别名）显示文章列表。</li></ol><blockquote><p>💡 静态首页模式下，首页的内容排版由该页面决定，可配合区块编辑器设计版面（见<a href="./07-block-editor">第 07 章</a>）。</p></blockquote><h3 id="常见问题-2" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题-2" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：设了静态首页后，博客列表页不见了？</strong> 答：多半是没指定「文章页」，或把「主页」和「文章页」选成了同一个页面——两者必须是不同的页面。</li></ul><h2 id="_5-6-设置-讨论" tabindex="-1">5.6 设置：讨论 <a class="header-anchor" href="#_5-6-设置-讨论" aria-label="Permalink to &quot;5.6 设置：讨论&quot;">​</a></h2><p>「设置 → 讨论」控制评论的全局开关、审核规则与头像显示，共六个板块。这里先记住最常用的三个开关：</p><ol><li>「允许他人在新文章上发表评论」——全站评论总闸（对已发布的旧文章不生效）。</li><li>「启用评论嵌套」——允许楼中楼回复。</li><li>「评论必须经人工批准」——最严格的审核策略。</li></ol><p>每个字段的精讲、审核关键词的写法、Akismet 反垃圾与评论模板定制，全部在<a href="./10-comments">第 10 章</a>展开。</p><h2 id="_5-7-设置-媒体" tabindex="-1">5.7 设置：媒体 <a class="header-anchor" href="#_5-7-设置-媒体" aria-label="Permalink to &quot;5.7 设置：媒体&quot;">​</a></h2><p>「设置 → 媒体」定义上传图片时 WordPress 自动生成的几种派生尺寸。</p><h3 id="原理说明-3" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-3" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>上传一张图，WordPress 会按这里的设置<strong>额外生成</strong>若干个尺寸的副本，主题在不同位置调用合适尺寸，避免「首页缩略图加载 4MB 原图」：</p><table tabindex="0"><thead><tr><th>尺寸</th><th>默认值</th><th>数值含义</th><th>用途举例</th></tr></thead><tbody><tr><td>缩略图大小</td><td>150 × 150</td><td>宽高的<strong>精确值</strong>，默认勾选「裁剪缩略图到精确尺寸」，不等比、直接裁出正方形</td><td>列表小图、相册网格</td></tr><tr><td>中等大小</td><td>300 × 300</td><td>宽高的<strong>上限</strong>，等比缩放，任一边不超过该值</td><td>文章内配图</td></tr><tr><td>大尺寸</td><td>1024 × 1024</td><td>同上，等比缩放的上限</td><td>正文大图、灯箱</td></tr></tbody></table><p>另外两个容易忽略的点：</p><ul><li><strong>2560 大图阈值</strong>：当上传图片的宽或高超过 2560 像素时，WordPress 会自动生成一张最大边 2560 的缩放副本作为「完整尺寸」（文件名带 <code>-scaled</code> 后缀），原图保留在服务器上但不直接使用。这个阈值可用过滤器调整。</li><li><strong>「以年—月文件夹整理上传内容」</strong>：勾选后文件存到 <code>uploads/2026/10/</code> 这样的目录，保持默认勾选便于维护。</li></ul><h3 id="操作方法-配置媒体尺寸" tabindex="-1">操作方法：配置媒体尺寸 <a class="header-anchor" href="#操作方法-配置媒体尺寸" aria-label="Permalink to &quot;操作方法：配置媒体尺寸&quot;">​</a></h3><ol><li>「设置 → 媒体」，先理解三档尺寸的定位再动手：缩略图服务列表与网格，中等服务正文插图，大服务通栏大图。</li><li>缩略图保持 150 × 150 并勾选「裁剪缩略图到精确尺寸」——相册网格需要正方形才整齐；若不勾选则等比缩放，网格会高低不一。</li><li>中等与大尺寸按主题正文的版心宽度调整：正文版心约 700 像素就把中等设 700 上限、大设 1200 上限，让插图清晰度与文件体积平衡。</li><li>确认「以年—月文件夹整理上传内容」保持勾选，保存更改。</li><li>上传一张宽 4000 像素的测试图，到媒体库查看详情：能看到自动生成的各尺寸与一张带 <code>-scaled</code> 后缀的「完整尺寸」。</li></ol><h3 id="常见问题-3" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题-3" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：改了这里的尺寸，以前上传的图片会变吗？</strong> 答：不会。尺寸设置只影响之后上传的图片；历史图片的派生尺寸需要重新生成，方法见<a href="./08-media-library">第 08 章</a>。</li></ul><h2 id="_5-8-设置-固定链接" tabindex="-1">5.8 设置：固定链接 <a class="header-anchor" href="#_5-8-设置-固定链接" aria-label="Permalink to &quot;5.8 设置：固定链接&quot;">​</a></h2><p>固定链接（Permalink）决定全站文章 URL 的长相，也是 SEO 与可维护性的地基。</p><p><img src="`+l+'" alt="图 05-4：固定链接设置页"><em>图 05-4：设置 → 固定链接：六种结构选项 + 分类/标签前缀设置，推荐选择「文章名」</em></p><h3 id="原理说明-4" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-4" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>URL 形态</th><th>评价</th></tr></thead><tbody><tr><td>朴素</td><td><code>/?p=123</code></td><td>不依赖伪静态，但无语义、不利于 SEO</td></tr><tr><td>日期和名称型</td><td><code>/2026/10/04/sample-post/</code></td><td>URL 冗长，且把时效钉死在地址里</td></tr><tr><td>月份和名称型</td><td><code>/2026/10/sample-post/</code></td><td>略短，仍带日期</td></tr><tr><td>数字型</td><td><code>/archives/123</code></td><td>无语义</td></tr><tr><td>文章名</td><td><code>/sample-post/</code></td><td><strong>推荐</strong>：简短、语义化、稳定</td></tr><tr><td>自定义结构</td><td>用 <code>%year%</code>、<code>%postname%</code> 等标签自由组合</td><td>有特殊需求时用</td></tr></tbody></table><p>下方「可选」区块可改<strong>分类目录前缀</strong>（默认 <code>category</code>）与<strong>标签前缀</strong>（默认 <code>tag</code>），改后归档地址变为 <code>/你的前缀/分类别名/</code>。前缀与分类树的规划联动，见<a href="./09-taxonomies">第 09 章</a>。</p><p><strong>伪静态依赖服务器 rewrite</strong>：非「朴素」结构需要 Web 服务器把 <code>/sample-post/</code> 这类漂亮地址内部转发给 WordPress 处理——</p><ul><li>Apache：依赖 <code>mod_rewrite</code> 与站点根目录的 <code>.htaccess</code>（保存固定链接时 WordPress 会尝试自动写入规则）；</li><li>Nginx：没有 <code>.htaccess</code> 机制，需要在站点配置里手写 <code>try_files</code> 规则，配置方法见<a href="./03-server-environment">第 03 章</a>。</li></ul><h3 id="操作方法-设置文章名结构" tabindex="-1">操作方法：设置文章名结构 <a class="header-anchor" href="#操作方法-设置文章名结构" aria-label="Permalink to &quot;操作方法：设置文章名结构&quot;">​</a></h3><ol><li>「设置 → 固定链接」，选择「文章名」（对应 <code>/%postname%/</code>）。</li><li>如使用 Nginx，确认服务器配置已含 <code>try_files $uri $uri/ /index.php?$args;</code>。</li><li>点「保存更改」。即使没有修改，<strong>点一次保存也会刷新重写规则</strong>——这是排查 404 的常用动作。</li><li>打开任意文章前台，确认 URL 变为 <code>/文章别名/</code> 且能正常访问。</li></ol><h3 id="常见问题-4" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题-4" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：保存固定链接后文章全部 404？</strong> 答：重写规则未生效。按顺序排查：① 再点一次「保存更改」；② Apache 检查 <code>.htaccess</code> 是否可写、虚拟主机是否允许 <code>AllowOverride</code>；③ Nginx 检查 <code>try_files</code> 是否配置并 reload。仍不行按<a href="./38-troubleshooting">第 38 章</a>的流程处理。</li></ul><h2 id="_5-9-设置-隐私" tabindex="-1">5.9 设置：隐私 <a class="header-anchor" href="#_5-9-设置-隐私" aria-label="Permalink to &quot;5.9 设置：隐私&quot;">​</a></h2><p>「设置 → 隐私」只做一件事：<strong>指定哪个页面是你的「隐私政策」</strong>。</p><h3 id="原理说明-5" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-5" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>只要站点收集任何访客数据——评论表单里的姓名与邮箱、注册账号、统计脚本的 Cookie——就需要一份公开可访问的隐私政策，告知访客数据被如何收集与使用。WordPress 把「隐私政策页面」做成一个一等设置项，是为了让主题、插件（尤其是评论表单与注册流程）有一个统一的地方去取这个页面的链接。</p><h3 id="操作方法-指定隐私政策页面" tabindex="-1">操作方法：指定隐私政策页面 <a class="header-anchor" href="#操作方法-指定隐私政策页面" aria-label="Permalink to &quot;操作方法：指定隐私政策页面&quot;">​</a></h3><ol><li>点「创建」可让 WordPress 生成一个带建议大纲的隐私政策草稿页，或在下拉中选择已有页面。</li><li>点「使用此页面」保存。主题与插件会在需要的位置（注册页、评论表单等）链接到它。</li><li>页面上的「指南」按钮提供按模块编写隐私政策的建议文本，可据此补全内容。</li></ol><p>配套工具在「工具」菜单里：「导出个人数据」与「抹除个人数据」，用于响应访客「把我的数据给我/删掉」的请求——把对方邮箱填进去，系统会发确认邮件，确认后打包导出或匿名化其评论等数据。</p><h2 id="_5-10-用户与权限体系" tabindex="-1">5.10 用户与权限体系 <a class="header-anchor" href="#_5-10-用户与权限体系" aria-label="Permalink to &quot;5.10 用户与权限体系&quot;">​</a></h2><h3 id="原理说明-6" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-6" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>WordPress 的权限模型是<strong>角色（Role）→ 能力（Capability）</strong>：每个角色是一组能力的命名集合，后台菜单、按钮、操作权限全部由能力决定。默认五大角色能力如下（✓ 表示拥有）：</p><table tabindex="0"><thead><tr><th>能力</th><th>管理员</th><th>编辑</th><th>作者</th><th>贡献者</th><th>订阅者</th></tr></thead><tbody><tr><td>阅读</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>撰写并编辑自己的文章</td><td>✓</td><td>✓</td><td>✓</td><td>✓（不能发布，只能提交待审）</td><td>—</td></tr><tr><td>上传图片等媒体文件</td><td>✓</td><td>✓</td><td>✓</td><td>—</td><td>—</td></tr><tr><td>发布文章</td><td>✓</td><td>✓</td><td>✓</td><td>—</td><td>—</td></tr><tr><td>编辑/删除他人文章</td><td>✓</td><td>✓</td><td>—</td><td>—</td><td>—</td></tr><tr><td>管理页面</td><td>✓</td><td>✓</td><td>—</td><td>—</td><td>—</td></tr><tr><td>审核评论</td><td>✓</td><td>✓</td><td>—</td><td>—</td><td>—</td></tr><tr><td>管理分类与标签</td><td>✓</td><td>✓</td><td>—</td><td>—</td><td>—</td></tr><tr><td>安装/管理主题与插件</td><td>✓</td><td>—</td><td>—</td><td>—</td><td>—</td></tr><tr><td>管理用户</td><td>✓</td><td>—</td><td>—</td><td>—</td><td>—</td></tr><tr><td>修改站点设置</td><td>✓</td><td>—</td><td>—</td><td>—</td><td>—</td></tr></tbody></table><h3 id="操作方法-快速体验角色差异" tabindex="-1">操作方法：快速体验角色差异 <a class="header-anchor" href="#操作方法-快速体验角色差异" aria-label="Permalink to &quot;操作方法：快速体验角色差异&quot;">​</a></h3><ol><li>「用户 → 添加用户」建一个作者角色的测试账号（勾选发送通知邮件）。</li><li>用浏览器的<strong>无痕窗口</strong>登录该账号（无痕窗口与主窗口会话隔离，两个账号可同时在线）。</li><li>观察左侧菜单：作者看不到「外观」「插件」「设置」「页面」「评论」。</li><li>在「文章 → 写文章」里写一段内容，作者可以直接点「发布」；再把该账号角色改回「贡献者」（管理员在「用户 → 全部用户」里快速编辑），重进无痕窗口写文章，此时只有「提交审核」按钮——亲身体验矩阵中那一格 <code>✓</code> 与 <code>—</code> 的差别。</li><li>体验完毕，管理员把测试账号删除或降回订阅者。</li></ol><h3 id="最小权限原则" tabindex="-1">最小权限原则 <a class="header-anchor" href="#最小权限原则" aria-label="Permalink to &quot;最小权限原则&quot;">​</a></h3><p>给协作者开账号时，<strong>只给完成工作所需的最小角色</strong>：</p><ul><li>投稿人 → 贡献者（写完提交审核，编辑把关）；</li><li>专职写手 → 作者（可自己发布）；</li><li>内容负责人 → 编辑（管全部内容与评论）；</li><li>技术运维才给管理员，且<strong>管理员账号越少越好</strong>，日常发文不要用管理员账号。</li></ul><p>角色给错了不只是「多点几个按钮」的问题：作者无法发布意味着误操作上不了线；编辑碰不到设置意味着改不坏全站。权限是安全事故的第一道闸门，更多加固手段见<a href="./32-security">第 32 章</a>。</p><h3 id="操作方法-新建用户" tabindex="-1">操作方法：新建用户 <a class="header-anchor" href="#操作方法-新建用户" aria-label="Permalink to &quot;操作方法：新建用户&quot;">​</a></h3><ol><li>「用户 → 添加用户」。</li><li>填「用户名」（登录用，创建后不可改）、「电子邮件」（接收通知与找回密码，必填且唯一）。</li><li>可选填姓名、站点、语言；点「显示密码」可查看/修改系统生成的强密码。</li><li>「角色」下拉选择合适角色；保持勾选「向新用户发送账号信息邮件」。</li><li>点「添加新用户」。对方收邮件后自行登录并在「个人资料」里改密。</li></ol><p><img src="'+h+'" alt="图 05-5：用户列表与角色列"><em>图 05-5：用户 → 全部用户：每行显示用户名、姓名、邮箱、角色与文章数，可按角色筛选、批量改角色</em></p><h3 id="个人资料的三个重点" tabindex="-1">个人资料的三个重点 <a class="header-anchor" href="#个人资料的三个重点" aria-label="Permalink to &quot;个人资料的三个重点&quot;">​</a></h3><p>每个用户在「用户 → 个人资料」里管理自己的账号信息，其中三项最常用：</p><ol><li><strong>公开显示名</strong>：先填「昵称」，再在「公开显示为」下拉里选前台署名（昵称/姓名组合）。<strong>不要让署名等于登录用户名</strong>——作者归档页地址 <code>/author/用户名/</code> 会暴露登录名，给暴力破解递梯子（防护见<a href="./32-security">第 32 章</a>）。</li><li><strong>头像（Gravatar）</strong>：WordPress 不本地存头像，而是按邮箱去 Gravatar（全球公认头像服务）取图。到 gravatar.com 用同一邮箱注册并上传头像，全互联网支持 Gravatar 的站点都会显示它。国内加载慢的解决方案见 <a href="#_5-12-常见问题速查">5.12 节</a>。</li><li><strong>应用密码（Application Passwords）</strong>：为 REST API、移动应用、外部自动化工具签发的<strong>专用密码</strong>，格式形如 <code>xxxx xxxx xxxx xxxx xxxx xxxx</code>。每个应用单独签发、可随时单独吊销，泄露一个不影响主密码。生成方法：个人资料底部「应用密码」区，输入应用名称 →「添加新应用密码」→ 立即复制（只显示一次）。生产环境要求站点启用 HTTPS 才能使用。</li></ol><h2 id="_5-11-站点健康" tabindex="-1">5.11 站点健康 <a class="header-anchor" href="#_5-11-站点健康" aria-label="Permalink to &quot;5.11 站点健康&quot;">​</a></h2><p>「工具 → 站点健康」是 WordPress 自带的体检仪，分两页：</p><p><img src="'+n+`" alt="图 05-6：站点健康状态页"><em>图 05-6：工具 → 站点健康：状态页列出关键问题与推荐改进，并显示通过测试的数量</em></p><h3 id="状态页" tabindex="-1">状态页 <a class="header-anchor" href="#状态页" aria-label="Permalink to &quot;状态页&quot;">​</a></h3><p>把检查结果分为两档：</p><ul><li><strong>关键问题</strong>：需要立即处理，例如 PHP 版本过旧、全站未启用 HTTPS、调试模式在生产环境开启、站点无法发起环回请求（影响定时任务与更新）。</li><li><strong>推荐改进</strong>：不紧急但建议处理，例如删除未使用的默认主题、移除失活插件、建议安装缺失的 PHP 扩展。</li></ul><p>页面顶部的百分比/计数是「通过测试」的数量，整改后点「重新检查」刷新。</p><h3 id="信息页" tabindex="-1">信息页 <a class="header-anchor" href="#信息页" aria-label="Permalink to &quot;信息页&quot;">​</a></h3><p>结构化列出站点全量配置：WordPress 版本与常量、目录大小与权限、主题与插件清单、服务器环境（Web 服务器、PHP 版本及各项 <code>ini</code> 参数）、数据库版本等。右上角「复制站点信息到剪贴板」可一键生成纯文本报告——<strong>去论坛或群里求助时附上它，比口头描述高效得多</strong>。</p><h3 id="常见问题-5" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题-5" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：状态页报「计划事件未能运行」/环回请求失败？</strong> 答：服务器无法自己访问自己，常见于本地环境域名未解析、或防火墙拦了出站请求。先按信息页确认环境，再按<a href="./38-troubleshooting">第 38 章</a>排查网络与主机配置。</li></ul><h2 id="_5-12-常见问题速查" tabindex="-1">5.12 常见问题速查 <a class="header-anchor" href="#_5-12-常见问题速查" aria-label="Permalink to &quot;5.12 常见问题速查&quot;">​</a></h2><ul><li><strong>问：同事登录后找不到「外观」「设置」菜单？</strong> 答：不是故障，是角色权限不足。到「用户 → 全部用户」看他的角色：作者/贡献者/订阅者本来就看不到这些菜单。确有需要再提升角色，且遵循 5.10 节的最小权限原则。</li><li><strong>问：固定链接保存后文章 404？</strong> 答：重写规则未生效。先回「设置 → 固定链接」再点一次保存强制刷新；Apache 确认 <code>.htaccess</code> 写入成功且站点允许覆写；Nginx 确认配置含 <code>try_files $uri $uri/ /index.php?$args;</code> 并已 reload。详见 5.8 节与<a href="./38-troubleshooting">第 38 章</a>。</li><li><strong>问：时区改成 UTC+8 了，旧文章的发布时间怎么没变？</strong> 答：发布时间按<strong>发布那一刻的站点时区</strong>写入数据库（同时存一份 UTC 时间），改时区只影响之后的显示换算与新内容，不会回写旧文章。显示异常时先确认改的是「设置 → 常规」里的站点时区，而非仅服务器系统时间。</li><li><strong>问：Gravatar 头像在国内加载很慢甚至裂图？</strong> 答：Gravatar 默认服务器在国内访问不稳定。三种解法任选：① 用兼容 Gravatar 协议的国内镜像（如 Cravatar），装对应替换插件即可，无需改数据；② 主题/插件层用过滤器替换头像域名（面向开发者，见<a href="./15-child-themes">第 15 章</a>）；③ 在「设置 → 讨论」底部直接取消「显示头像」，最省事。</li><li><strong>问：管理员密码忘了、重置邮件也收不到，怎么进后台？</strong> 答：三种方法按场景选—— <ol><li><strong>邮件找回</strong>（邮件功能正常时）：登录页「忘记密码？」走标准流程。</li><li><strong>phpMyAdmin 改哈希</strong>：进数据库打开 <code>wp_users</code> 表，编辑管理员那一行，<code>user_pass</code> 字段的函数列选 <strong>MD5</strong>、值列填新密码明文，保存后即可用新密码登录（WordPress 登录成功时会自动把它升级为安全哈希）。</li><li><strong>WP-CLI</strong>（有服务器命令行时，推荐）：</li></ol></li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 按用户名重置，密码用引号包住防特殊字符</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user_pass=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;NewStrongPass!2026&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 不确定管理员用户名时先列出全部用户</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><blockquote><p>💡 方法 2、3 属于「绕过登录」的运维操作，用完即走；日常应保证管理邮箱可用，让方法 1 永远有效。找回后建议立即检查「用户」列表里有无陌生账号（见<a href="./32-security">第 32 章</a>）。</p></blockquote><h2 id="本章总结" tabindex="-1">本章总结 <a class="header-anchor" href="#本章总结" aria-label="Permalink to &quot;本章总结&quot;">​</a></h2><ol><li>登录走 <code>wp-login.php</code>，后台入口是 <code>/wp-admin</code>；管理栏是登录后前后台切换与快速新建的枢纽，可在个人资料中关闭前台显示。</li><li>左侧主菜单十项各司其职，菜单按角色裁剪——菜单「消失」先查角色，不是故障。</li><li>「设置 → 常规」里 WordPress 地址是程序目录、站点地址是前台入口，移动目录必须「先改地址、立刻挪文件」，改错可用 <code>wp_options</code> 或 WP-CLI 修复；时区、成员资格、默认角色都在这一页把关。</li><li>阅读设置决定首页形态：博客流或「静态首页 + 文章页」；媒体设置的三个尺寸是等比上限（缩略图除外，可精确裁剪），2560 是「完整尺寸」的大图阈值；固定链接推荐 <code>/%postname%/</code>，非朴素结构依赖服务器 rewrite。</li><li>五大默认角色能力递减，协作遵循最小权限原则；个人资料里管好公开显示名、Gravatar 与应用密码。</li><li>「工具 → 站点健康」分关键问题与推荐改进两档，信息页的「复制站点信息」是求助标配；密码三找回法（邮件 / phpMyAdmin MD5 / <code>wp user update</code>）至少掌握两种。</li></ol><h2 id="动手练习" tabindex="-1">动手练习 <a class="header-anchor" href="#动手练习" aria-label="Permalink to &quot;动手练习&quot;">​</a></h2><p><strong>练-05-01（操作题）｜五个角色的账号各建一个，体验权限差异</strong></p><p>在「用户 → 添加用户」中分别创建管理员之外的四个角色账号（编辑、作者、贡献者、订阅者各一，加上你自己的管理员共五个）。用浏览器的无痕窗口逐个登录，把每个角色实际看到的左侧菜单记录下来，与 5.10 节的能力矩阵逐格核对。重点验证三件事：贡献者写文章时有没有「发布」按钮、能不能上传图片；作者能否看到别人的文章；订阅者登录后还能做什么。</p><p><strong>练-05-02（操作题）｜配置静态首页 + 博客页</strong></p><p>新建「首页」「博客」两个页面（「首页」用区块编辑器简单排版一段欢迎语），在「设置 → 阅读」中把首页显示切换为静态页面并指定两者。验证：域名直达首页；博客页地址显示文章列表；再把设置改回「您的最新文章」，确认前台恢复博客流。思考：两种形态分别适合什么类型的站点？</p><p><strong>练-05-03（操作题）｜用 WP-CLI 重置管理员密码</strong></p><p>在本地环境终端执行 <code>wp user list</code> 找到管理员用户名，再用 <code>wp user update 用户名 --user_pass=&#39;你设定的新密码&#39;</code> 重置。退出后台后用新密码重新登录验证。加分项：故意把密码改成一个弱密码，登录后观察后台/站点健康有没有相关提示，然后改回强密码。</p><p><strong>练-05-04（操作题）｜设置六分页巡检</strong></p><p>对照本章 5.3–5.9 节，把你练习站的六个设置分页逐项核对一遍并填表：每项当前值、本章建议值、是否需要修改。其中必须完成：副标题清空或改写、时区 UTC+8、默认角色为订阅者、固定链接为文章名结构、确认未勾选「对搜索引擎的可见性」（开发站除外）。</p><p><strong>练-05-05（综合题）｜站点健康整改到「零关键问题」</strong></p><p>打开「工具 → 站点健康」，把状态页列出的每一条关键问题与推荐改进抄下来，逐条查明原因并处理（本地练习站常见的有：HTTPS 未启用、调试模式开启、未使用的默认主题与插件）。整改完成后点「重新检查」，目标是关键问题清零，并用「信息」页的复制功能导出一份站点信息存档。</p>`,152)])])}const P=d(p,[["render",c]]);export{q as __pageData,P as default};
